#!/usr/bin/env python3
"""Ratings you can trust, reported per batch (source) and cumulatively, and admins are never blocked.
- Each error is counted once, whoever pointed at it. Catch rate = errors a peer pointed at / all known errors.
- A reviewer's catch rate = what they pointed at / all known errors on their sources.
- New Process report (per source, then the total across all sources) with an Excel download.
- Admins can always edit; the edit is logged with the lock reason it overrode.
Run from the repo root. Safe to run twice."""
import os, sys, json, zlib, base64
sys.stdout.reconfigure(errors='replace')
SYNC = json.loads('{"backend/app/services/record_locks.py": "", "backend/app/services/quality.py": "", "backend/app/api/v1/routes/quality.py": "", "frontend/src/components/enh/ProcessReport.tsx": "", "frontend/src/pages/Quality.tsx": ""}')
OPS = json.loads('[["backend/app/api/v1/routes/sources.py", "lock_override = _rl.assert_record_editable(source, record, current_user)\\n    before = dict(", "    _rl.assert_record_editable(source, record)\\n    before = dict(", "    lock_override = _rl.assert_record_editable(source, record, current_user)\\n    before = dict("], ["backend/app/api/v1/routes/sources.py", "\\"changed_by\\": current_user.id, \\"lock_override\\"", "\\"changed_by\\": current_user.id,", "\\"changed_by\\": current_user.id, \\"lock_override\\": lock_override,"], ["backend/app/api/v1/routes/sources.py", "lock_override = _rl.assert_record_editable(source, record, current_user)\\n    db.add(AuditLog(", "    _rl.assert_record_editable(source, record)\\n    db.add(AuditLog(", "    lock_override = _rl.assert_record_editable(source, record, current_user)\\n    db.add(AuditLog("], ["backend/app/api/v1/routes/sources.py", "\\"deleted_by\\": current_user.id, \\"lock_override\\"", "\\"deleted_by\\": current_user.id,", "\\"deleted_by\\": current_user.id, \\"lock_override\\": lock_override,"], ["backend/app/api/v1/routes/records.py", "assert_record_editable(_src, r, current_user)", "_rl.assert_record_editable(_src, r)", "_rl.assert_record_editable(_src, r, current_user)"]]')
ok = True

def rd(p):
    raw = open(p, 'rb').read().decode('utf-8'); return raw, ('\r\n' in raw), raw.replace('\r\n', '\n')
def wr(p, t, crlf): open(p, 'wb').write((t.replace('\n', '\r\n') if crlf else t).encode('utf-8'))

for path, b in SYNC.items():
    new = zlib.decompress(base64.b64decode(b))
    if os.path.exists(path):
        old, crlf, t = rd(path)
        if t.encode('utf-8') == new: print("same      ", path); continue
        bk = os.path.join(os.path.expanduser("~/xtrium_backup_45"), path)
        os.makedirs(os.path.dirname(bk), exist_ok=True); open(bk, 'wb').write(old.encode('utf-8'))
        verb = "replaced  "
    else:
        crlf = False; verb = "created   "; os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    wr(path, new.decode('utf-8'), crlf); print(verb, path)

by = {}
for f, mark, anchor, new in OPS: by.setdefault(f, []).append((mark, anchor, new))
S = "backend/app/api/v1/routes/sources.py"
by.setdefault(S, [])
for f, steps in by.items():
    if not os.path.exists(f): print("MISSING   ", f); ok = False; continue
    raw, crlf, t = rd(f)
    for mark, anchor, new in steps:
        if mark in t: print("already   ", f.split('/')[-1], mark[:40].strip()); continue
        if t.count(anchor) != 1: print("NO MATCH  ", f, mark[:50]); ok = False; continue
        t = t.replace(anchor, new, 1); print("applied   ", f.split('/')[-1], mark[:40].strip())
    if f == S:
        BOLD, BNEW, CLOG = ('    _rl.assert_bulk_editable(source)\n', '    _bulk_override = _rl.assert_bulk_editable(source, current_user)\n', '    db.add(AuditLog(user_id=current_user.id, project_id=source.project_id, source_id=source.id, action=AuditAction.SOURCE_RECORD_FIXED,\n                    after_value={"cleared_all_records": True, "cleared_by": current_user.id, "lock_override": _bulk_override, "status_at_clear": source.status.value}))\n')
        if "_bulk_override" in t: print("already    bulk checks")
        elif t.count(BOLD) == 4:
            t = t.replace(BOLD, BNEW)
            i = t.index("# clear_records.lock"); j = t.index(BNEW, i)
            t = t[:j] + BNEW + CLOG + t[j + len(BNEW):]
            print("applied    bulk checks (4) and the clear log")
        else: print("NO MATCH   bulk checks in sources.py (found %d of 4)" % t.count(BOLD)); ok = False
    wr(f, t, crlf)

# anchored additions to shared files
def add_before(path, mark, anchor, text):
    global ok
    if not os.path.exists(path): print("MISSING   ", path); ok = False; return
    raw, crlf, t = rd(path)
    if mark in t: print("already   ", path.split('/')[-1], mark); return
    if t.count(anchor) != 1: print("NO MATCH  ", path, mark); ok = False; return
    wr(path, t.replace(anchor, text + anchor, 1), crlf); print("applied   ", path.split('/')[-1], mark)
add_before("frontend/src/api/client.ts", "processReport:", "  exportExtractorReport: async (", "  processReport: (params: { project_id?: string; source_id?: string; date_from?: string; date_to?: string }) => api.get('/quality/process-report', { params }).then(r => r.data),\n  exportProcessReport: async (params: { project_id?: string; source_id?: string; date_from?: string; date_to?: string }) => {\n    const r = await api.get('/quality/process-report/export', { params, responseType: 'blob' })\n    const url = URL.createObjectURL(new Blob([r.data]))\n    const a = document.createElement('a'); a.href = url; a.download = `process_report_${new Date().toISOString().slice(0, 10)}.xlsx`; a.click(); URL.revokeObjectURL(url)\n  },\n")
p = "backend/app/services/quality_export.py"
if os.path.exists(p):
    raw, crlf, t = rd(p)
    if "def process_workbook" in t: print("already    quality_export.py process_workbook")
    else: wr(p, t.rstrip('\n') + "\n" + '\n\ndef process_workbook(sc: dict, meta: dict) -> bytes:\n    """The whole process in one workbook: the cumulative total, one row per source (batch), each extractor and each peer reviewer.\n    Every number comes from the same counts, and the README says exactly how each rate is worked out."""\n    wb = Workbook()\n    ws = wb.active\n    ws.title = "README"\n    window = " to ".join(x for x in (meta.get("date_from"), meta.get("date_to")) if x) or "everything ever recorded"\n    gen = _fmt(meta.get("generated"))\n    lines = [\n        "Process report: accuracy, errors and review catch across the sources.",\n        f"Period: {window}.  Generated: {gen} (UTC).",\n        "",\n        "Sheets",\n        "Cumulative: the total across all sources in this report.",\n        "Batches: one row per source (each source is one Xtrium batch), highest error rate first.",\n        "Extractors: the same figures grouped by the extractor assigned to each source.",\n        "Reviewers: each peer reviewer\'s catches, false alarms and catch rate.",\n        "",\n        "How each number is worked out",\n        "Error: one record and field that an admin confirmed as wrong, or that an admin\'s check against the real source found wrong. Counted once, however many people pointed at it. Errors stay counted after the extractor fixes them.",\n        "Errors per 100 fields = errors / fields delivered x 100.",\n        "First-pass accuracy = checked fields that were right the first time / checked fields. It never changes after a fix.",\n        "Final accuracy = checked fields that are right now / checked fields whose current value was checked. A field changed since its check is \'waiting re-check\' and left out until it is checked again.",\n        "Catch rate = errors a peer reviewer pointed at / all known errors. Only errors an admin has confirmed or found count, so it can rise as more fields are checked.",\n        "Reviewer catch rate = errors that reviewer pointed at / all known errors on the sources they were assigned to.",\n        "Reviewer precision = fields the reviewer flagged that were confirmed / (confirmed + dismissed).",\n        "Rework rate = records sent back at least once / records.",\n        "Confidence is \'low\' when fewer than 30 fields were checked (fewer than 10 known errors for a reviewer). Treat low-confidence rates as early signals.",\n        "Edits made after peers began reviewing are locked. An admin override is logged, so scores can be re-run with it excluded.",\n    ]\n    for i, line in enumerate(lines, 1):\n        ws.cell(i, 1, line)\n        if i in (1, 4, 10):\n            ws.cell(i, 1).font = Font(bold=True)\n    ws.column_dimensions["A"].width = 150\n    head = PatternFill("solid", fgColor="1F2937")\n\n    def sheet(title, cols, rows):\n        w = wb.create_sheet(title)\n        w.append(cols)\n        for c in w[1]:\n            c.font, c.fill = Font(bold=True, color="FFFFFF"), head\n        for r in rows:\n            w.append([_cell(v) for v in r])\n        w.freeze_panes = "A2"\n        for i, c in enumerate(cols, 1):\n            w.column_dimensions[get_column_letter(i)].width = max(12, min(40, len(c) + 4))\n        return w\n\n    def pc(v):\n        return "" if v is None else v / 100.0\n    num_cols = ["Records", "Fields", "Checked", "Errors", "Errors per 100 fields", "First-pass accuracy", "Final accuracy", "Caught by peers", "Missed by peers", "Catch rate", "Fixed", "Still wrong", "Records sent back", "Rework rate", "Confidence"]\n\n    def nums(d):\n        return [d["records"], d["fields"], d["audited"], d["errors"], d["errors_per_100"], pc(d["first_pass_accuracy"]), pc(d["final_accuracy"]), d["caught"], d["escaped"], pc(d["caught_rate"]),\n                d["fixed"], d["still_wrong"], d["returned_records"], pc(d["rework_rate"]), d["confidence"]]\n    c = sc["cumulative"]\n    sheet("Cumulative", ["Sources"] + num_cols, [[c.get("sources", 0)] + nums(c)])\n    sheet("Batches", ["Source", "Status", "Extractor", "Peer reviewers"] + num_cols,\n          [[b["source"], b.get("status", ""), b["extractor"], ", ".join(b["peers"])] + nums(b) for b in sc["batches"]])\n    sheet("Extractors", ["Extractor", "Sources"] + num_cols, [[x["name"], len(x["sources"])] + nums(x) for x in sc["extractors"]])\n    sheet("Reviewers", ["Reviewer", "Sources assigned", "Known errors on them", "Caught", "Missed", "Catch rate", "False alarms", "Precision", "Still open", "Only one to catch", "Confidence"],\n          [[r["name"], r["sources"], r["known_errors"], r["caught"], r["missed"], pc(r["catch_rate"]), r["false_alarms"], pc(r["precision"]), r["open"], r["only_one_to_catch"], r["confidence"]] for r in sc["reviewers"]])\n    for name in ("Cumulative", "Batches", "Extractors", "Reviewers"):\n        w = wb[name]\n        for row in w.iter_rows(min_row=2):\n            for cell in row:\n                h = w.cell(1, cell.column).value\n                if h in ("First-pass accuracy", "Final accuracy", "Catch rate", "Rework rate", "Precision") and isinstance(cell.value, float):\n                    cell.number_format = "0.0%"\n    bio = io.BytesIO()\n    wb.save(bio)\n    return bio.getvalue()\n', crlf); print("applied    quality_export.py process_workbook")
else: print("MISSING   ", p); ok = False
print()
print("All applied." if ok else "Some edits did not match: paste the lines above and I will fit them to your files.")
